INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, title_ar, text_plain, origin, printed_page, data_json) VALUES ('blk_kay_seg_77c653907aecb73e', 'khalil_kitab_ayn', 're_kay_51c54105f94a8694', 'sec_kay_1409b1df3ad04561', 'علو', 'e1.a1', 11, 2, 'definition', 'ar', 'العلو: أصل البناء (شاهد قرآني)', 'العُلُوٌّ للهِ سبحانَه وتَعَالَى عن كلِّ شيء فهو أعلى وأعظم مما يُثْنَى عليه، لا إله إلا الله وحده لا شريك له. والعلو: أصل البناء. ومنه العَلاءُ والعُلُوّ، فالعَلاءُ الرِّفْعَةُ، والعُلُوُّ العظمة والتجبّر. [يقال] : علا مَلِكٌ في الأرض [أي: طغَى وتعظّم] . قال الله عزّ وجلّ: إِنَّ فِرْعَوْنَ عَلا فِي الْأَرْضِ «1» . ', 'derived_segmentation', 598, '{"span": [2, 319]}');
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, title_ar, text_plain, origin, printed_page, data_json) VALUES ('blk_kay_seg_264b789d9c1aa379', 'khalil_kitab_ayn', 're_kay_51c54105f94a8694', 'sec_kay_1409b1df3ad04561', 'علو', 'e1.a2', 12, 2, 'definition', 'ar', 'رجلٌ عالي الكعب، أي: شريف · العَلْياء: رأسُ كلّ جَبَلٍ مُشْرِف', 'ورجلٌ عالي الكعب، أي: شريف. قال «2» :
لمّا عَلا كَعْبُكَ لي عَلِيتُ
[وتقول] لكلّ شيء علا: علا يَعْلو علوا، و [تقول] في الرِّفعة والشرف: عَلِيَ يَعْلى عَلاءً. والعَلْياء: رأسُ كلّ جَبَلٍ مُشْرِف. قال «3» :
تحملن بالعلياء من فوق جرثم
والعالية: القناة المستقيمة. والجمع: العوالي. [ويُسمّى أعلى القناة: العالية. ', 'derived_segmentation', 598, '{"span": [319, 627]}');
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, title_ar, text_plain, origin, printed_page, data_json) VALUES ('blk_kay_seg_7ea978249f8b7084', 'khalil_kitab_ayn', 're_kay_51c54105f94a8694', 'sec_kay_1409b1df3ad04561', 'علو', 'e1.a3', 13, 2, 'definition', 'ar', 'أسفلُها: السّافِلَة · المَعْلاةُ: كَسْبُ الشَّرَفِ من المعالي', 'وأسفلُها: السّافِلَة] «4» . والمَعْلاةُ: كَسْبُ الشَّرَفِ من المعالي. والعالية من محلّة العرب: الحجاز وما يليها، والنّسبة إليها: عُلْويّ. وعُلْوُ كلّ شيء أعلاه تَرْفَع العَيْنَ وتخفِضُ. وذهب في السّماء عُلْواً وفي الأرض سُفْلاً. والعُلْوُ والسُّفْلُ: أعلى كلّ شيء وأسفله. و [يقال] : سِفْلُ الدّارِ وعِلْوُها، وسُفْلُها وعُلْوُها. ', 'derived_segmentation', 598, '{"span": [627, 957]}');
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, title_ar, text_plain, origin, printed_page, data_json) VALUES ('blk_kay_seg_05ea3210154c83d1', 'khalil_kitab_ayn', 're_kay_51c54105f94a8694', 'sec_kay_1409b1df3ad04561', 'علو', 'e1.a4', 14, 2, 'definition', 'ar', 'فلان من عِلْية الناس، أي: من أهل الشَّرَفْ (شاهد قرآني)', 'وفلان من عِلْية الناس، أي: من أهل الشَّرَفْ. وهؤلاء عِلْيَةُ قومهم. مكسورة العين، على فِعْلَة خفيفة. والعُلِّيَّة: الغُرفة على بناء حُرّيّة، في التّصريف على: فُعُّولة. وعاليةُ الوادي: أعلاه، وسافلتُه: أسفلُه، وفي كلّ شيء كذلك، عُلْيا مضر، وسُفْلى مضر. إذا قلت: عُليا قلت: سُفْلَى، وإذا قلت: عُلْو قلت: سفل. والسماوات العُلَى. الواحدة عُلْيا. ', 'derived_segmentation', 598, '{"span": [957, 1299]}');
