INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, title_ar, text_plain, origin, printed_page, data_json) VALUES ('blk_kay_seg_69f5f03674421b50', 'khalil_kitab_ayn', 're_kay_51c54105f94a8694', 'sec_kay_1409b1df3ad04561', 'علو', 'e1.a7', 17, 2, 'definition', 'ar', '(على): صفة من الصّفات · علاك، أي: عليك · يقولون: كنت على', 'والثّنايا العُلْيا، والثّنايا السُّفْلَى. والله تبارَكَ وتعالَى هو العليّ العالي المتعالي ذو العُلَى والمعالي تعالَى عمّا يقولُ الظالمون علوا كبيرا. و (على) : صفة من الصّفات، وللعرب فيه ثلاث لغات: على زيدٍ مال، وعليك مال. ويقال: علاك، أي: عليك. ويقولون: كنت على
السّطح، وكنت في أعلَى السّطح. ويقولون: في موضع أعلى عالٍ، وفي موضع أعلى علٍ. قال أبو النجم «6» :
أقبُّ من تحتُ عريضٌ من علِ
وقد ترفعُه العربُ في الغاية فيقولون: من علُ. قال عبد الله بن رَواحة:
', 'derived_segmentation', 598, '{"span": [1380, 1835]}');
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, title_ar, text_plain, origin, printed_page, data_json) VALUES ('blk_kay_seg_ef83a5c81237a6f1', 'khalil_kitab_ayn', 're_kay_51c54105f94a8694', 'sec_kay_1409b1df3ad04561', 'علو', 'e1.a8', 18, 2, 'poetry_quote', 'ar', 'شاهد شعري', 'شهِدْتُ فلم أكذبْ بأنّ محمّداً ... رسول الذي سوّى السماوات من علُ
