INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, title_ar, text_plain, origin, printed_page, data_json) VALUES ('blk_kay_seg_77ec3e817032bbdf', 'khalil_kitab_ayn', 're_kay_51c54105f94a8694', 'sec_kay_1409b1df3ad04561', 'علو', 'e1.a9', 19, 2, 'definition', 'ar', 'ف: قام فقد علا عنه · فتقول: تعالَ يا رجلُ · عَلْوَى: اسم فرس كان في الجاهلية', 'ويقال: اعْلُ عن مَجْلِسِك. فإذا قام فقد علا عنه. وتعلّتِ المرأة فهي تتعلَّى إذا طَهُرت من نفاسها. وتقول: يا رجل تعالَهْ، الهاءُ صِلَة، فإذا وصلتَ طرحتَ الهاء. فتقول: تعالَ يا رجلُ، وتعاليا وتعالَوْا، وأماتوا هذا الفعل سوى النّداء. وعَلْوَى: اسم فرس كان في الجاهلية. والعلاوة: رأس الجمل وعُنُقه. والعلاوة: رأس الرّجل وعُنُقه. ', 'derived_segmentation', 598, '{"span": [1901, 2226]}');
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, title_ar, text_plain, origin, printed_page, data_json) VALUES ('blk_kay_seg_3f86c6d480282116', 'khalil_kitab_ayn', 're_kay_51c54105f94a8694', 'sec_kay_1409b1df3ad04561', 'علو', 'e1.a10', 20, 2, 'definition', 'ar', 'العلاوة: ما يحمل على البعير · عَلِيّ: اسم على فعيل', 'والعلاوة: ما يحمل على البعير والحمار فوق العِدْلينِ بعد تمام الوقر، والجميع: علاوات. وتقول: أعطيك ألفاً وديناراً علاوة. والجمع العَلاوَى على وزن فَعالَى، كالهِراوَة والهَراوَى.
وقال أبو سفيان: اعلُ هُبَل، فقال النبي صلى الله عليه وآله وسلّم: الله أَعْلَى وأَجَلّ.
وعَلِيّ: اسم على فعيل، إذا نُسِبَ إليه قيل: عَلَويّ. ', 'derived_segmentation', 598, '{"span": [2226, 2543]}');
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, title_ar, text_plain, origin, printed_page, data_json) VALUES ('blk_kay_seg_6905a166b01933bb', 'khalil_kitab_ayn', 're_kay_51c54105f94a8694', 'sec_kay_1409b1df3ad04561', 'علو', 'e1.a11', 21, 2, 'definition', 'ar', 'المُعَلَّى · الفَرَسُ: جرى في الرّهان وبلغ الغاية', 'والمُعَلَّى: القِدْحُ الأوّل يخرج في الميسر. وكلّ من قهر امرأً أو عدوّاً فقد علا واعتلاه واستعلى عليه. والفَرَسُ إذا جرى في الرّهان وبلغ الغاية، قيل: استعلَى على الغاية واستولى. ويقال: عُلْوان الكتاب، وأظنه غلطاً، وإنّما هو عُنوان. والعِليانْ: الذّكر من الضّباع. والبعير الضخم أيضا.
وعِلِّيِّينَ: جماعة علِّيٍّ في السماء السابعة يُصْعَدُ إليه بأرواحِ المؤمنين. ', 'derived_segmentation', 598, '{"span": [2543, 2904]}');
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, title_ar, text_plain, origin, printed_page, data_json) VALUES ('blk_kay_seg_b85b73ba7356c995', 'khalil_kitab_ayn', 're_kay_51c54105f94a8694', 'sec_kay_1409b1df3ad04561', 'علو', 'e1.a12', 22, 2, 'definition', 'ar', 'العَلاةُ', 'والعَلاةُ: النّاقة الصُّلبة تُشَبّهُ بالعَلاة وهي السّندان.
