INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, title_ar, text_plain, origin, printed_page, data_json) VALUES ('blk_kay_seg_a6aa9aa6c89b05e8', 'khalil_kitab_ayn', 're_kay_51c54105f94a8694', 'sec_kay_1409b1df3ad04561', 'علو', 'e1.a13', 23, 2, 'definition', 'ar', 'عول · العالةُ: الفريضة · العَوْلُ: الميل في الحكم', 'عول: العَوْلُ: ارتفاع الحساب في الفرائض. والعالةُ: الفريضة. تَعُول عَوْلاً. ويقالُ للفارض: اعلُ الفريضة. والعَوْلُ: الميل في الحكم، أي: الجَوْر. والعَوْل: كلّ أمرٍ عالكَ. قالت الخنساء «7» :
', 'derived_segmentation', 598, '{"span": [2964, 3154]}');
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, title_ar, text_plain, origin, printed_page, data_json) VALUES ('blk_kay_seg_0cbc1199aa4c6c35', 'khalil_kitab_ayn', 're_kay_51c54105f94a8694', 'sec_kay_1409b1df3ad04561', 'علو', 'e1.a14', 24, 2, 'poetry_quote', 'ar', 'شاهد شعري', 'يُكلّفُه القومُ ما عالَهُمْ ... وإن كان أصْغَرَهُمْ مَولدا
