INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, title_ar, text_plain, origin, printed_page, data_json) VALUES ('blk_kay_seg_6a3701b9d628d759', 'khalil_kitab_ayn', 're_kay_51c54105f94a8694', 'sec_kay_1409b1df3ad04561', 'علو', 'e1.a15', 25, 2, 'definition', 'ar', 'العَوْل أيضاً: المُعَوَّل · عَوَّلَ عليه: اقتصر عليه', 'والعَوْلة من العَويل، وهو البكاء. أعْوَلَتِ المرأة إعوالاً، وهو شدّة صياحِها عند بكاء أو مكروه نزل بها. والعَوْل أيضاً: المُعَوَّل. عَوَّلَ عليه: اقتصر عليه، ولم يختر عليه. وعوّلتُ عليه: استعنتُ به، ومعناه: صيّرتُ أمري إليه. وتقول: أبفلانٍ تعوّل عليّ وبكذا إذا نازعك في أمرٍ يتطاول عليك. قال «8» :
وليس على دهرٍ لشيءٍ مُعَوَّل
وقال «9» :
عندي ولا في القومِ من مُعوّل
', 'derived_segmentation', 598, '{"span": [3213, 3580]}');
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, title_ar, text_plain, origin, printed_page, data_json) VALUES ('blk_kay_seg_28ae5fdb254deed4', 'khalil_kitab_ayn', 're_kay_51c54105f94a8694', 'sec_kay_1409b1df3ad04561', 'علو', 'e1.a16', 26, 2, 'definition', 'ar', 'العَوْل: قُوتُ العِيال · المِعْوَل: حديدة ينقر بها الجبال', 'والعَوْل: قُوتُ العِيال. هو يَعُولهم عولاً. والمِعْوَل: حديدة ينقر بها الجبال، قال «10» :
أنيابها كالمعاول', 'derived_segmentation', 598, '{"span": [3580, 3686]}');
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, title_ar, text_plain, origin, printed_page, data_json) VALUES ('blk_kay_seg_4ff1a36f22ad21d2', 'khalil_kitab_ayn', 're_kay_d70471b7283fa774', 'sec_kay_65537266d05b61c0', 'رب', 'e1.a1', 11, 2, 'definition', 'ar', 'الرِّبِّيُّون: الّذين صبروا مع الأنبياء · الرَّبابُ: السَّحابُ الذي فيه ماء', 'الرِّبِّيُّون: الّذين صبروا مع الأنبياء، نسبوا إلى العبادة والتّألّه في معرفة الرُّبوبيّة للَّه، الواحد: رِبِّيٌّ. ومن ملك شيئاً فهو رَبُّه، لا يُقال بغير الإضافة إلاّ للَّهِ عزّ وجل. ورجلٌ ربّابيّ نسب إلى الرّبّاب، حيّ من ضَبَّة. والرَّبابُ: السَّحابُ الذي فيه ماء، الواحدةُ: رَبابة، وأَرَبَّتِ السَّحابة بهذه البلدة: أدامَتْ بها المَطَر، قال:
أربّ بها عارضٌ مُمْطِرُ «3»
', 'derived_segmentation', 3027, '{"span": [2, 375]}');
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, title_ar, text_plain, origin, printed_page, data_json) VALUES ('blk_kay_seg_14636730870266b5', 'khalil_kitab_ayn', 're_kay_d70471b7283fa774', 'sec_kay_65537266d05b61c0', 'رب', 'e1.a2', 12, 2, 'definition', 'ar', 'أرضٌ مِربابٌ: أَرّبَّ بها المطر', 'وأرضٌ مِربابٌ: أَرّبَّ بها المطر، ومرب أيضا، لا يزال بها مطر، وكذلك مَصَلّ، فيها صِلالٌ من مَطَر، أي: أمطار متفرّقة، شيء بعد شيء، قال «4» :
