INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, title_ar, text_plain, origin, printed_page, data_json) VALUES ('blk_kay_seg_0ad4fa1298382114', 'khalil_kitab_ayn', 're_kay_42b9bfa898e81bf7', 'sec_kay_87d3100ca5036ff1', 'بين', 'e1.a5', 15, 2, 'definition', 'ar', 'ناب · النّاب: النّاقةُ المُسِنّة · النّائبة: النّازلة', 'ناب: النّاب: السّنّ الذي خلف الرّباعية، وهو النّاب مذكّر، وأنياب: جمعه. والنّاب: النّاقةُ المُسِنّة، والجميع: نيبٌ وأنياب. والنّائبة: النّازلة، يقال: ناب هذا الأمرُ نوبةً، أي: نزل. ونابتهم نوائب الدّهر. وأناب فلانٌ إلى الله إنابة، فهو مُنِيبٌ، إذا نابَ ورجع إلى الطّاعة. وناب عنّي فلان في هذا الأمر نيابة، إذا قام مَقامَك. وتناوبنا الخطب والأمر نتناوَبُه، إذا قمتما به نوبة بعد نوبة، قال:
', 'derived_segmentation', 3151, '{"span": [727, 1116]}');
